// 1. 获取当前循环的图片和提示词 (使用 .item 精准获取当前循环项)
const base64String = $('Extract from File1').item.json.data;
const promptText = $('Edit Fields1').item.json.promt;

if (!base64String) {
    throw new Error("兜底分支获取图片失败");
}

// 2. 清理 Base64 前缀 (Ollama 要求纯 base64)
const cleanBase64 = base64String.replace(/^data:image\/\w+;base64,/, '');

// 3. 构建 Ollama 请求Payload
const ollamaPayload = {
    // ⚠️ 记得换成你本地跑的视觉模型，比如 llava, bakllava, minicpm-v
    model: "gemma4:e4b", 
    messages: [
        {
            role: "system",
            content: promptText
        },
        {
            role: "user",
            content: "请严格根据系统设定的标准对这张图片进行评分，只输出合法的 JSON 格式数据。",
            images: [cleanBase64]
        }
    ],
    stream: false,
    format: "json" // 强制要求 Ollama 输出 JSON
};

return { json: { requestBody: ollamaPayload, source: "Ollama_Fallback" } };

// 1. 获取提示词
const promptText = $("Edit Fields1").first().json.promt;

// 2. 获取已经由上一个节点提取到 JSON 中的 Base64 字符串
const base64String = $input.item.json.data;

if (!base64String) {
    throw new Error("❌ 在 JSON 中找不到提取好的图片数据！请检查 Extract from File 节点是否成功执行。");
}

// 3. 提取 MIME 类型（尝试从残留的 binary 对象中取，取不到就默认 jpeg）
let mimeType = "image/jpeg";
if ($input.item.binary && $input.item.binary.data && $input.item.binary.data.mimeType) {
    mimeType = $input.item.binary.data.mimeType;
}

// 4. 智能组装图片 URL
// 因为不同版本的 n8n 提取结果不同，有的是纯 base64，有的自带 "data:image/jpeg;base64," 前缀。这里做一个智能判断。
const finalImageUrl = base64String.startsWith('data:') 
    ? base64String 
    : `data:${mimeType};base64,${base64String}`;

// 5. 组装大模型请求 Payload
const doubaoPayload = {
    model: "doubao-seed-2-0-lite-260215",
    messages: [
        {
            role: "system",
            content: promptText
        },
        {
            role: "user",
            content: [
                {
                    type: "text",
                    text: "请根据系统设定的标准对这张图片进行评分，只输出合法的 JSON。"
                },
                {
                    type: "image_url",
                    image_url: {
                        url: finalImageUrl
                    }
                }
            ]
        }
    ],
    // 如果后续 HTTP 请求报错说 payload 太大，可以尝试把 max_tokens 加回来
};

// 输出最终的请求体，准备传给 HTTP Request 节点
return { json: { requestBody: doubaoPayload } };

// 1. 获取当前流经的数据，并自动剥离外层可能存在的数组外壳
let inputData = $input.item.json;
if (Array.isArray(inputData)) {
    inputData = inputData[0];
}

let aiContent = "";
let engineName = "Unknown";

// 2. 智能探针：根据特征字段自动匹配解析路径
if (inputData.choices && inputData.choices.length > 0 && inputData.choices[0].message) {
    aiContent = inputData.choices[0].message.content;
    engineName = inputData.model || "Doubao_API";
} else if (inputData.message && inputData.message.content) {
    aiContent = inputData.message.content;
    engineName = inputData.model || "Ollama_Fallback";
} else {
    throw new Error("❌ 未知的 API 响应结构，提取失败: " + JSON.stringify(inputData).substring(0, 200));
}

// 3. 清洗大模型输出的 Markdown 标记并解析 JSON
let cleanJsonStr = aiContent.replace(/```json/gi, '').replace(/```/g, '').trim();
let resultData = {};

try {
    resultData = JSON.parse(cleanJsonStr);
} catch (e) {
    throw new Error(`❌ JSON 解析失败! 引擎[${engineName}] 返回了不规范的内容: ` + aiContent);
}

// 4. 定级核心逻辑
let level = "D_淘汰";
const score = resultData.total_score || 0;

if (resultData.is_approved) {
    level = score >= 45 ? "S_极品" : "A_优秀";
} else if (score >= 35) {
    level = "B_备选";
} else if (score >= 25) {
    level = "C_一般";
}

// 5. 获取原始文件信息
const currentLoopItem = $('Loop Over Items4').item;
const fileName = currentLoopItem.binary.data.fileName;

// 跨节点溯源：从「收集Worker目录」节点获取当前图片所属的文件夹名
let rawDataDir = "";
try {
    rawDataDir = $('收集Worker目录').item.json.dir_part;
} catch(e) {
    try {
        rawDataDir = $('收集Worker目录').first().json.dir_part;
    } catch(e2) {
        // 兼容旧版：回退到格式化结果1
        try {
            const rawObj = $('格式化结果1').item.json.raw;
            const firstKey = Object.keys(rawObj)[0];
            rawDataDir = rawObj[firstKey].output_dir.split("\\")[1];
        } catch(e3) {
            rawDataDir = '';
        }
    }
}

// 6. 生成操作命令
const sourceFilePath = `/tmp/pin_images/${rawDataDir}/images/${fileName}`;
const targetDirPath = `/tmp/pin_images/${rawDataDir}/classified/${level}`;

const shellCmd = `export LANG=C.UTF-8 && mkdir -p "${targetDirPath}" && cp "${sourceFilePath}" "${targetDirPath}/"`;

// 7. 输出统一标准的 JSON
return {
    json: {
        engine: engineName,
        fileName: fileName,
        folderName: rawDataDir,
        level: level,
        score_data: resultData,
        command: shellCmd
    }
};

const baseParams = $('设置参数').first().json;
const workers = baseParams.workers || 1;
const perWorkerPins = Math.ceil(baseParams.max_pins / workers);

const workerTasks = [];
for (let i = 0; i < workers; i++) {
  const isPrimary = (i === 0);
  const workerPins = (i === workers - 1) 
    ? baseParams.max_pins - perWorkerPins * (workers - 1) 
    : perWorkerPins;

  workerTasks.push({
    json: {
      query: baseParams.query,
      max_pins: workerPins,
      min_saves: baseParams.min_saves,
      min_comments: baseParams.min_comments,
      media_type: baseParams.media_type,
      download_images: baseParams.download_images,
      climb_mode: baseParams.climb_mode,
      use_folder_structure: baseParams.use_folder_structure,
      chrome_port: baseParams.chrome_port + i,
      chrome_headless: isPrimary ? baseParams.chrome_headless : false,
      debug: baseParams.debug,
      worker_id: `worker-${i}`,
      chrome_profile: isPrimary ? '' : `worker_${i}`,
      enable_ai_filter: true,
      site: 'pinterest',
      _worker_index: i,
      _total_workers: workers
    }
  });
}

return workerTasks;

const allProgress = $input.first().json;
let output = '=== 全部Worker结果 ===\n';
let totalCollected = 0;
const rawResults = {};

for (const [wid, progress] of Object.entries(allProgress)) {
  const stage = progress.stage || 'unknown';
  const collected = progress.collected_count || 0;
  totalCollected += collected;
  output += `[${wid}] 状态: ${stage === 'completed' ? '✅成功' : stage === 'error' ? '❌失败' : stage}\n`;
  output += `[${wid}] 收集: ${collected} 个\n`;
  if (progress.output_dir) output += `[${wid}] 目录: ${progress.output_dir}\n`;
  rawResults[wid] = progress;
}

output += `\n📊 总计收集: ${totalCollected} 个\n`;

return [{ json: { text: output, raw: rawResults, total_collected: totalCollected } }];

const rawResults = $input.first().json.raw;
const imageItems = [];

for (const [wid, progress] of Object.entries(rawResults)) {
  const outputDir = progress.output_dir;
  if (!outputDir) continue;
  const dirPart = outputDir.split('\\')[1] || outputDir.split('/')[1] || '';
  imageItems.push({
    json: {
      worker_id: wid,
      output_dir: outputDir,
      dir_part: dirPart,
      collected_count: progress.collected_count || 0
    }
  });
}

if (imageItems.length === 0) {
  imageItems.push({ json: { worker_id: 'none', output_dir: '', dir_part: '', collected_count: 0 } });
}

return imageItems;
